import type { Context } from 'cordis'
// Loaded by the host before plugins. No clocks, hooks, observers or timers until opted in.
export const PERFORMANCE_KEY = 'tilr.performance.enabled'
/** How far back the live history (samples, events, metric buckets) reaches, ms. */
export const HISTORY = 120_000
/** The 1 s sampler's period, ms. */
export const SAMPLE_INTERVAL = 1000
const MAX_EVENTS = 20_000
/** Cordis handler events live in a ring of their own: a chatty event bus cannot evict React,
 *  frame or input events from the main buffer. */
const MAX_HANDLER_EVENTS = 5_000
const MAX_FIBERS = 20_000
/**
 * The rAF loop runs only while something reads frame data: the Performance window is open
 * (`demand('window')`), a recording runs (`demand('recording')`), or `metrics()` (the exporter)
 * was read within the last FRAME_DEMAND_MS. Otherwise no rAF callback is scheduled and a
 * sample's FPS / frame percentiles are null ("n/a"); the 1 s sampler keeps running.
 */
export const FRAME_DEMAND_MS = 5_000
/** A native process reply arriving later than this after the previous one marks its sample
 *  `late`: the page's main thread was blocked (the request is driven by the page's timer). */
export const STALL_MS = 1_500
/** At most this many metric series (name + labels); observations of further ones are counted in
 *  `dropped.series`. */
export const MAX_SERIES = 512
/** Each series keeps its last METRIC_RING observations (for p50 / p95 / max of a recent window). */
export const METRIC_RING = 256
/** Per-second (count, sum) buckets each series keeps: the history the window draws. */
const METRIC_SECONDS = 120
const METRIC_NAME = /^[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*$/
const LABEL_NAME = /^[a-zA-Z_][a-zA-Z0-9_]*$/
const MAX_LABELS = 8
const MAX_LABEL_VALUE = 128
/** Event Timing entries recorded as `input` events (and input.* metrics). */
const INPUT_TYPES = new Set(['keydown', 'keyup', 'pointerdown', 'pointerup', 'click', 'wheel'])
const COMPONENT_TAGS = [0, 1, 11, 14, 15]

/** Event Timing of one input: `delay` = processingStart - startTime, `processing` =
 *  processingEnd - processingStart (ms); the event's `duration` is until the next paint. */
export interface InputTiming { type: string; delay: number; processing: number }
export interface PerfEvent { t: number; kind: string; plugin: string; name: string; duration: number | null; window?: string; count?: number; detail?: ReactDetail; input?: InputTiming }
export interface ProcessMetric { pid: number; name: string; scope: string; cpu: number | null; cpuSeconds: number; memory: number }
/** `late`: the native process reply came more than STALL_MS after the previous one (a
 *  main-thread stall); `gap`: the ms between the two replies. */
export interface PerfSample { t: number; visible: boolean; fps: number | null; frameP95: number | null; frameMax: number | null; commits: number; renderMs: number; processes: ProcessMetric[]; listeners?: Record<string, number>; late?: boolean; gap?: number }
/**
 * One metric series in a snapshot / recording: what `metric(name, value, labels)` observed.
 * Times are `performance.now()` ms of the page (the recording's `origin` is its timeOrigin).
 */
export interface PerfMetric {
  /** Dotted lowercase: `server.decode`. */
  name: string
  /** Sorted by key; string values only. */
  labels: Record<string, string>
  /** Since the series' first observation in this collection session (not clipped to the
   *  snapshot's window). */
  count: number
  sum: number
  min: number
  max: number
  last: number
  /** When `last` was observed. */
  t: number
  /** The latest observations (at most METRIC_RING, 256) inside the snapshot's window, oldest
   *  first, as [t, value]. */
  recent: [number, number][]
  /** Per-second buckets inside the snapshot's window (at most 120), oldest first, as
   *  [second, count, sum] with second = Math.floor(t / 1000); seconds without observations
   *  are left out. */
  seconds: [number, number, number][]
}
/**
 * The recording format, version 1. `dropped`: what bounded buffers dropped inside the
 * recording's window, by event kind (`react`, `component`, `handler`, …), plus `series` (metric
 * observations refused at MAX_SERIES) and `invalid` (malformed metric() calls). `metrics` is
 * absent in recordings made before metrics existed.
 */
export interface PerfRecording { version: 1; origin: number; react: string; started: number; ended: number; samples: PerfSample[]; events: PerfEvent[]; dropped: Record<string, number>; metrics?: PerfMetric[] }
interface Total { commits: number; renders: number; renderMs: number; loads: number; reloads: number; starts: number; errors: number; operationMs: number; handlers: number; handlerMs: number; loadMs: number; loadBuckets: number[] }
export interface Fiber {
  tag: number; flags: number; actualDuration?: number; child?: Fiber; sibling?: Fiber; return?: Fiber; alternate?: Fiber | null; subtreeFlags?: number;
  type?: { name?: string; displayName?: string }; memoizedProps?: Record<string, unknown>; memoizedState?: unknown;
  dependencies?: { firstContext?: ContextDependency | null } | null; stateNode?: unknown;
}
interface ContextDependency { context: unknown; memoizedValue?: unknown; next?: ContextDependency | null }
export interface ReactDetail { id: number; parent: number | null; depth: number; reason: string; props: string[]; selfMs: number | null; candidate: boolean }
/** Inferences from committed Fiber data, never proof that a render was unnecessary. No values are retained. */
export function renderReason(fiber: Fiber): Pick<ReactDetail, 'reason' | 'props' | 'candidate'> {
  const before = fiber.alternate
  if (!before) return { reason: 'mount', props: [], candidate: false }
  const props: string[] = []
  const a = before.memoizedProps ?? {}, b = fiber.memoizedProps ?? {}
  const keys = [...new Set([...Object.keys(a), ...Object.keys(b)])]
  for (const key of keys.slice(0, 100)) if (!Object.is(a[key], b[key]) || Object.hasOwn(a, key) !== Object.hasOwn(b, key)) props.push(key.slice(0, 100))
  const reasons = props.length ? ['props changed (identity/value)'] : []
  if (keys.length > 100) reasons.push('props comparison truncated')
  // Hook lists are implementation details; only queued state/reducer hooks are compared.
  let stateChanged = false
  if (fiber.tag === 1) stateChanged = !Object.is(before.memoizedState, fiber.memoizedState)
  else {
    type Hook = { memoizedState?: unknown; queue?: unknown; next?: Hook | null }
    let old = before.memoizedState as Hook | null, next = fiber.memoizedState as Hook | null
    let n = 0
    while (old && next && n++ < 100) {
      if ((old.queue || next.queue) && !Object.is(old.memoizedState, next.memoizedState)) stateChanged = true
      old = old.next ?? null; next = next.next ?? null
    }
    if (old || next) reasons.push('hooks changed or comparison incomplete')
  }
  if (stateChanged) reasons.push('state/reducer changed')
  let oldContext = before.dependencies?.firstContext, nextContext = fiber.dependencies?.firstContext
  let contexts = 0
  while (oldContext && nextContext && contexts++ < 100) {
    if (oldContext.context !== nextContext.context || !Object.is(oldContext.memoizedValue, nextContext.memoizedValue)) { reasons.push('context changed'); break }
    oldContext = oldContext.next; nextContext = nextContext.next
  }
  if ((oldContext || nextContext) && !reasons.includes('context changed')) reasons.push('context comparison incomplete')
  const candidate = reasons.length === 0
  return { reason: candidate ? 'same observed inputs; parent update or unknown cause' : reasons.join('; '), props, candidate }
}

interface ReactRoot { current?: Fiber; containerInfo?: Element }
interface ReactHook { supportsFiber?: boolean; isDisabled?: boolean; renderers?: Map<number, unknown>; inject?: (renderer: unknown) => number; onCommitFiberRoot?: (id: number, root: ReactRoot, ...rest: unknown[]) => void }
interface NativeBridge { postMessage(value: string): Promise<ProcessMetric[]> }
const globals = globalThis as typeof globalThis & {
  __REACT_DEVTOOLS_GLOBAL_HOOK__?: ReactHook
  webkit?: { messageHandlers?: { tilrPerformance?: NativeBridge } }
}
export let performanceCollector: PerformanceCollector | undefined
export function performanceRequested(): boolean {
  try { return sessionStorage.getItem(PERFORMANCE_KEY) === 'on' } catch { return false }
}
export function requestPerformance(on: boolean): void {
  sessionStorage.setItem(PERFORMANCE_KEY, on ? 'on' : 'off')
}
export function bootPerformance(): void {
  // An older native shell may still inject its legacy collector: never run both.
  if (globalThis.__tilrPerf) return
  if (!performanceCollector && performanceRequested()) performanceCollector = new PerformanceCollector()
}
export function stopPerformance(): void {
  performanceCollector?.dispose()
  performanceCollector = undefined
}
export function percentile(values: number[], q: number): number | null {
  if (!values.length) return null
  const sorted = [...values].sort((a, b) => a - b)
  return sorted[Math.max(0, Math.ceil(sorted.length * q) - 1)]
}
const label = (s: string) => s.replaceAll('\\', '\\\\').replaceAll('"', '\\"').replaceAll('\n', '\\n')

/** Adds `item` to `list` (sorted by `t`) after the items with the same or an earlier `t`. */
function insert<T extends { t: number }>(list: T[], item: T): void {
  if (!list.length || list[list.length - 1].t <= item.t) { list.push(item); return }
  let lo = 0, hi = list.length
  while (lo < hi) { const mid = (lo + hi) >>> 1; if (list[mid].t <= item.t) lo = mid + 1; else hi = mid }
  list.splice(lo, 0, item)
}

/** The first index of `list` (sorted by `t`) whose `t` is >= `t`. */
export function lowerBound(list: readonly { t: number }[], t: number): number {
  let lo = 0, hi = list.length
  while (lo < hi) { const mid = (lo + hi) >>> 1; if (list[mid].t < t) lo = mid + 1; else hi = mid }
  return lo
}

/** p50 / p95 / max of `values` came from all observations of the window (`full`), or only from
 *  the series' ring of the latest METRIC_RING, which does not reach back to the window's start
 *  (`tail`: older observations of the window were overwritten). */
export type Coverage = 'full' | 'tail'

/** Whether `m.recent` covers (from, …]: not when the ring has overwritten observations (count >
 *  METRIC_RING), is full and its oldest entry is newer than `from`. */
export function coverage(m: Pick<PerfMetric, 'count' | 'recent'>, from: number): Coverage {
  return m.count > METRIC_RING && m.recent.length >= METRIC_RING && m.recent[0][0] > from ? 'tail' : 'full'
}

/**
 * What the window and `tilr ctl debug metrics` show of a series over (end - window, end]:
 * observations/s from the per-second buckets of the whole seconds inside the window (the
 * partial oldest and the partial current second are left out), p50 / p95 / max of the recent
 * values, `n` of them and their `coverage`.
 */
export function metricStats(m: PerfMetric, end: number, window = 10_000): { rate: number; p50: number | null; p95: number | null; max: number | null; values: number[]; n: number; coverage: Coverage } {
  const from = end - window
  const values: number[] = []
  for (const [t, v] of m.recent) if (t > from && t <= end) values.push(v)
  const first = Math.ceil(from / 1000), last = Math.floor(end / 1000) - 1
  let count = 0
  for (const [second, n] of m.seconds) if (second >= first && second <= last) count += n
  const seconds = last - first + 1
  return { rate: seconds > 0 ? count / seconds : 0, p50: percentile(values, 0.5), p95: percentile(values, 0.95), max: values.length ? Math.max(...values) : null, values, n: values.length, coverage: coverage(m, from) }
}

/** Prometheus text for metric series: `tilr_metric_{count,sum}` (counters since the series'
 *  first observation; values are non-negative, so `_sum` only grows) and
 *  `tilr_metric_{p50,p95,max}` (gauges over the values of the last `window` ms, left out when
 *  there are none) with `tilr_metric_n` (how many values) and `tilr_metric_tail` (1: the ring of
 *  the latest 256 did not reach back over the whole window), with the metric's `name` and its
 *  labels. */
export function metricExposition(metrics: readonly PerfMetric[], now: number, window = 60_000): string[] {
  const out: string[] = []
  const stats = metrics.map(m => metricStats(m, now, window))
  const labels = (m: PerfMetric) => [`name="${label(m.name)}"`, ...Object.entries(m.labels).map(([k, v]) => `${k}="${label(v)}"`)].join(',')
  const family = (name: string, type: string, value: (m: PerfMetric, stats: ReturnType<typeof metricStats>) => number | null) => {
    out.push(`# TYPE ${name} ${type}`)
    for (const [i, m] of metrics.entries()) {
      const v = value(m, stats[i])
      if (v !== null) out.push(`${name}{${labels(m)}} ${v}`)
    }
  }
  family('tilr_metric_count', 'counter', m => m.count)
  family('tilr_metric_sum', 'counter', m => m.sum)
  family('tilr_metric_p50', 'gauge', (_, s) => s.p50)
  family('tilr_metric_p95', 'gauge', (_, s) => s.p95)
  family('tilr_metric_max', 'gauge', (_, s) => s.max)
  family('tilr_metric_n', 'gauge', (_, s) => s.n || null)
  family('tilr_metric_tail', 'gauge', (_, s) => s.n ? (s.coverage === 'tail' ? 1 : 0) : null)
  return out
}

/** One series of `metric()`: totals, a ring of the last METRIC_RING observations and
 *  per-second buckets over METRIC_SECONDS. Fixed size from the first observation on. */
class Series {
  count = 0; sum = 0; min = Infinity; max = -Infinity; last = 0; t = 0
  private readonly times = new Float64Array(METRIC_RING)
  private readonly values = new Float64Array(METRIC_RING)
  private next = 0
  private size = 0
  private readonly secondIds = new Float64Array(METRIC_SECONDS).fill(-1)
  private readonly secondCounts = new Float64Array(METRIC_SECONDS)
  private readonly secondSums = new Float64Array(METRIC_SECONDS)
  readonly name: string
  readonly labels: Readonly<Record<string, string>>
  constructor(name: string, labels: Readonly<Record<string, string>>) { this.name = name; this.labels = labels }
  /** `t` is when the observation happened, which may be earlier than the previous one's (an
   *  Event Timing entry's startTime): the ring is sorted when read, and a second older than the
   *  buckets reach back is left out of them (never overwrites a newer one). */
  add(t: number, value: number): void {
    this.count++; this.sum += value
    if (t >= this.t) { this.last = value; this.t = t }
    if (value < this.min) this.min = value
    if (value > this.max) this.max = value
    this.times[this.next] = t; this.values[this.next] = value
    this.next = (this.next + 1) % METRIC_RING
    if (this.size < METRIC_RING) this.size++
    const second = Math.floor(t / 1000), slot = ((second % METRIC_SECONDS) + METRIC_SECONDS) % METRIC_SECONDS
    if (this.secondIds[slot] > second) return
    if (this.secondIds[slot] !== second) { this.secondIds[slot] = second; this.secondCounts[slot] = 0; this.secondSums[slot] = 0 }
    this.secondCounts[slot]++; this.secondSums[slot] += value
  }
  view(since: number, now: number): PerfMetric {
    const recent: [number, number][] = []
    let sorted = true
    for (let i = 0; i < this.size; i++) {
      const at = (this.next - this.size + i + METRIC_RING) % METRIC_RING
      if (this.times[at] >= since) {
        if (recent.length && recent[recent.length - 1][0] > this.times[at]) sorted = false
        recent.push([this.times[at], this.values[at]])
      }
    }
    if (!sorted) recent.sort((a, b) => a[0] - b[0])
    const seconds: [number, number, number][] = []
    const last = Math.floor(now / 1000)
    for (let second = Math.max(Math.floor(since / 1000), last - METRIC_SECONDS + 1); second <= last; second++) {
      const slot = ((second % METRIC_SECONDS) + METRIC_SECONDS) % METRIC_SECONDS
      if (this.secondIds[slot] === second && this.secondCounts[slot]) seconds.push([second, this.secondCounts[slot], this.secondSums[slot]])
    }
    return { name: this.name, labels: { ...this.labels }, count: this.count, sum: this.sum, min: this.min, max: this.max, last: this.last, t: this.t, recent, seconds }
  }
}

export class PerformanceCollector {
  readonly origin = performance.timeOrigin
  readonly started = performance.now()
  readonly samples: PerfSample[] = []
  /** Everything but Cordis handler calls, bounded to MAX_EVENTS (20,000), sorted by `t`. */
  readonly events: PerfEvent[] = []
  /** Cordis handler calls (`handler`), bounded to MAX_HANDLER_EVENTS (5,000), sorted by `t`. */
  readonly handlers: PerfEvent[] = []
  readonly marks = new Map<string, number>()
  readonly totals = new Map<string, Total>()
  readonly listeners = new Set<() => void>()
  /** Metric series by name + sorted labels. */
  readonly series = new Map<string, Series>()
  /** Everything the bounded buffers dropped in this session, by kind (see PerfRecording). */
  readonly dropped: Record<string, number> = {}
  analysisPlugin: string | null = null
  highlight = false
  private dropLog: { t: number; kind: string; n: number }[] = []
  private fiberIDs = new WeakMap<Fiber, number>()
  private nextFiberID = 1
  private flashes: HTMLElement[] = []
  private flashPending: Element[] = []
  private flashFrame = 0
  private flashTimer: ReturnType<typeof setTimeout> | undefined
  analyze(plugin: string | null, highlight = false): void {
    this.analysisPlugin = plugin
    this.highlight = !!plugin && highlight
    this.fiberIDs = new WeakMap()
    this.clearHighlights()
  }
  private clearHighlights(): void {
    if (this.flashTimer !== undefined) clearTimeout(this.flashTimer)
    this.flashTimer = undefined
    if (this.flashFrame) cancelAnimationFrame(this.flashFrame)
    this.flashFrame = 0
    this.flashPending = []
    for (const el of this.flashes) el.remove()
    this.flashes = []
  }
  private fiberID(fiber: Fiber): number {
    const id = this.fiberIDs.get(fiber) ?? (fiber.alternate && this.fiberIDs.get(fiber.alternate)) ?? this.nextFiberID++
    this.fiberIDs.set(fiber, id)
    return id
  }
  /** Notes the rendered host element during the commit; its rectangle is read after the commit,
   *  in the next frame, never inside React's commit hook (that would force a layout there). */
  private flash(fiber: Fiber): void {
    if (this.flashes.length + this.flashPending.length >= 20) return
    const queue = [fiber]
    let n = 0
    while (queue.length && n++ < 100) {
      const item = queue.pop()
      if (!item) continue
      if (item.stateNode instanceof Element) {
        this.flashPending.push(item.stateNode)
        if (!this.flashFrame) this.flashFrame = requestAnimationFrame(() => this.drawFlashes())
        return
      }
      for (let child = item.child, count = 0; child && count++ < 100; child = child.sibling) queue.push(child)
    }
  }
  private drawFlashes(): void {
    this.flashFrame = 0
    const pending = this.flashPending
    this.flashPending = []
    if (this.disposed || !this.highlight) return
    for (const el of pending) {
      if (!el.isConnected) continue
      const rect = el.getBoundingClientRect()
      const box = document.createElement('div')
      box.style.cssText = `position:fixed;pointer-events:none;z-index:2147483647;border:2px solid #ff8c00;box-sizing:border-box;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px`
      document.body.append(box); this.flashes.push(box)
    }
    if (this.flashTimer !== undefined) clearTimeout(this.flashTimer)
    this.flashTimer = setTimeout(() => this.clearHighlights(), 180)
  }
  private frame = 0
  private framing = false
  private frameFrom = 0
  private frameUntil = 0
  private demands = new Map<string, number>()
  private timer: ReturnType<typeof setInterval>
  private lastFrame = 0
  private lastSample = this.started
  private deltas: number[] = []
  private intervalCommits = 0
  private intervalRender = 0
  private pending = false
  private disposed = false
  private processes: ProcessMetric[] = []
  private processAt = 0
  private replyAt = 0
  private observers: PerformanceObserver[] = []
  private lagChannel: MessageChannel | undefined
  private lagSent: number | null = null
  private restoreHook: () => void
  private restoreEvents: (() => void) | undefined
  private subscriptions: () => Record<string, number> = () => ({})
  private frameBuckets = [0, 0, 0, 0, 0, 0]
  private frameSum = 0
  private frameCount = 0
  /** React roots whose last commit left a tree (an unmount commits an empty one). */
  private roots = new Set<ReactRoot>()
  private visibility = () => { this.lastFrame = 0; this.frameFrom = 0; this.deltas = []; this.lastSample = performance.now(); this.replyAt = 0 }

  constructor() {
    this.restoreHook = this.reactHook()
    // One collector owns browser observations and lag sampling. Only entry types the engine
    // lists are observed: WebKit has no `longtask` / `layout-shift` (the lag probe and the
    // Event Timing `event` entries stand in for them).
    if (typeof PerformanceObserver !== 'undefined') {
      const supported = PerformanceObserver.supportedEntryTypes
      for (const type of ['resource', 'navigation', 'mark', 'measure', 'event']) {
        if (!supported.includes(type)) continue
        try {
          const observer = new PerformanceObserver(list => {
            for (const entry of list.getEntries()) {
              if (this.disposed) return
              if (type === 'event') this.input(entry as PerformanceEventTiming)
              else this.event(type, 'page', entry.name.split(/[?#]/)[0], entry.duration)
            }
          })
          observer.observe(type === 'event' ? { type, buffered: true, durationThreshold: 16 } as PerformanceObserverInit : { type, buffered: true })
          this.observers.push(observer)
        } catch { /* Unsupported in this host. */ }
      }
    }
    if (typeof window !== 'undefined' && typeof MessageChannel !== 'undefined') {
      this.lagChannel = new MessageChannel()
      this.lagChannel.port1.onmessage = () => {
        if (!this.disposed && this.lagSent !== null) this.event('lag', 'page', 'Main-thread task delay', performance.now() - this.lagSent)
        this.lagSent = null
      }
    }
    document.addEventListener('visibilitychange', this.visibility)
    this.timer = setInterval(() => this.sample(), SAMPLE_INTERVAL)
  }
  /**
   * Something that reads frame data starts (`on`) or stops needing it: `'window'` (the
   * Performance window is open), `'recording'`. Counted per reason. See FRAME_DEMAND_MS.
   */
  demand(reason: string, on: boolean): void {
    const n = (this.demands.get(reason) ?? 0) + (on ? 1 : -1)
    if (n > 0) this.demands.set(reason, n)
    else this.demands.delete(reason)
    this.frames()
  }
  /** Whether the rAF loop runs now. */
  get framesOn(): boolean { return this.framing }
  private wantsFrames(): boolean {
    return !this.disposed && (this.demands.size > 0 || performance.now() < this.frameUntil)
  }
  private frames(): void {
    if (!this.wantsFrames()) { this.stopFrames(); return }
    if (this.framing) return
    this.framing = true; this.lastFrame = 0; this.frameFrom = 0; this.deltas = []
    this.frame = requestAnimationFrame(this.tick)
  }
  private stopFrames(): void {
    if (this.framing) cancelAnimationFrame(this.frame)
    this.framing = false; this.frame = 0; this.lastFrame = 0; this.frameFrom = 0; this.deltas = []
  }
  private tick = (t: number): void => {
    if (!this.framing) return
    // Demand ran out (the exporter stopped reading): no further frame is requested.
    if (!this.wantsFrames()) { this.framing = false; this.frame = 0; this.lastFrame = 0; this.frameFrom = 0; this.deltas = []; return }
    if (this.lastFrame && document.visibilityState === 'visible') {
      const delta = t - this.lastFrame
      this.deltas.push(delta)
      const seconds = delta / 1000
      this.frameSum += seconds; this.frameCount++
      ;[0.00834, 0.01667, 0.025, 0.05, 0.1, Infinity].forEach((bound, i) => { if (seconds <= bound) this.frameBuckets[i]++ })
      if (delta > 50) this.event('frame', 'page', 'Long frame interval', delta)
    } else this.frameFrom = t
    this.lastFrame = t
    this.frame = requestAnimationFrame(this.tick)
  }
  private total(plugin: string): Total {
    let total = this.totals.get(plugin)
    if (!total) {
      total = { commits: 0, renders: 0, renderMs: 0, loads: 0, reloads: 0, starts: 0, errors: 0, operationMs: 0, handlers: 0, handlerMs: 0, loadMs: 0, loadBuckets: [0, 0, 0, 0, 0, 0] }
      this.totals.set(plugin, total)
    }
    return total
  }
  /** Counts `n` dropped items of `kind`, for the session and for recordings (by time). */
  private drop(kind: string, n: number): void {
    if (!n) return
    this.dropped[kind] = (this.dropped[kind] ?? 0) + n
    const t = performance.now()
    const last = this.dropLog.at(-1)
    // Drops of one kind within a second share an entry: the log stays small under a flood.
    // The entry keeps its first `t`: it spans at most a second from there, so a recording that
    // starts later does not count drops from before it.
    if (last && last.kind === kind && t - last.t < 1000) last.n += n
    else this.dropLog.push({ t, kind, n })
  }
  /** Records an event at `at` (now when omitted; an earlier time is inserted in order: the
   *  buffers stay sorted by `t`); the recorded event (undefined once disposed). */
  event(kind: string, plugin: string, name: string, duration: number | null = null, count?: number, window?: string, at?: number): PerfEvent | undefined {
    if (this.disposed) return
    plugin = plugin.slice(0, 128)
    if (!this.totals.has(plugin) && this.totals.size >= 511) plugin = 'other'
    name = name.slice(0, 512)
    const t = at ?? performance.now()
    const event: PerfEvent = { t, kind, plugin, name, duration, ...(count === undefined ? {} : { count }), ...(window ? { window } : {}) }
    if (kind === 'handler') {
      insert(this.handlers, event)
      if (this.handlers.length > MAX_HANDLER_EVENTS) { const trim = MAX_HANDLER_EVENTS / 4; this.handlers.splice(0, trim); this.drop('handler', trim) }
    } else {
      insert(this.events, event)
      if (this.events.length > MAX_EVENTS) {
        const removed = this.events.splice(0, MAX_EVENTS / 4)
        const kinds = new Map<string, number>()
        for (const e of removed) kinds.set(e.kind, (kinds.get(e.kind) ?? 0) + 1)
        for (const [k, n] of kinds) this.drop(k, n)
      }
    }
    if (kind === 'mark') { this.marks.delete(name); this.marks.set(name, t); if (this.marks.size > 512) { const first = this.marks.keys().next().value; if (first !== undefined) this.marks.delete(first) } }
    const total = this.total(plugin)
    if (kind === 'load') total.loads++
    if (kind === 'reload') total.reloads++
    if ((kind === 'load' || kind === 'reload') && duration !== null) {
      total.loadMs += duration
      ;[0.001, 0.01, 0.1, 1, 5, Infinity].forEach((bound, i) => { if (duration / 1000 <= bound) total.loadBuckets[i]++ })
    }
    if (kind === 'start') total.starts++
    if (kind === 'error') total.errors++
    if (kind === 'operation') total.operationMs += duration ?? 0
    if (kind === 'handler') { total.handlers++; total.handlerMs += duration ?? 0 }
    return event
  }
  /** One observation of a metric ('tilr' `metric()`), made at `at` (now when omitted); see
   *  PerfMetric. Values are non-negative: invalid names, negative or non-finite values are counted
   *  in `dropped.invalid`; labels that are not strings are left out. */
  metric(name: string, value: number, labels?: Readonly<Record<string, string>>, at?: number): void {
    if (this.disposed) return
    if (typeof name !== 'string' || name.length > 128 || !METRIC_NAME.test(name) || typeof value !== 'number' || !Number.isFinite(value) || value < 0) { this.drop('invalid', 1); return }
    let key = name
    let clean: Record<string, string> | undefined
    if (labels && typeof labels === 'object') {
      const keys = Object.keys(labels).filter(k => typeof labels[k] === 'string' && k !== 'name' && !k.startsWith('__') && LABEL_NAME.test(k)).sort().slice(0, MAX_LABELS)
      if (keys.length) {
        clean = {}
        for (const k of keys) { const v = labels[k].slice(0, MAX_LABEL_VALUE); clean[k] = v; key += `\u0000${k}\u0001${v}` }
      }
    }
    let series = this.series.get(key)
    if (!series) {
      if (this.series.size >= MAX_SERIES) { this.drop('series', 1); return }
      series = new Series(name, Object.freeze(clean ?? {}))
      this.series.set(key, series)
    }
    series.add(at ?? performance.now(), value)
  }
  /** The series as PerfMetric, `recent` / `seconds` from `since` on. */
  metricList(since: number): PerfMetric[] {
    const now = performance.now()
    return [...this.series.values()].map(s => s.view(since, now))
  }
  /** An Event Timing entry, at its own `startTime` (when the input happened, not when the
   *  observer delivered it; buffered entries replayed at boot keep theirs). */
  private input(entry: PerformanceEventTiming): void {
    if (!INPUT_TYPES.has(entry.name)) return
    const t = entry.startTime
    const delay = Math.max(0, entry.processingStart - t)
    const processing = Math.max(0, entry.processingEnd - entry.processingStart)
    const event = this.event('input', 'page', entry.name, entry.duration, undefined, undefined, t)
    if (event) event.input = { type: entry.name, delay, processing }
    const labels = { type: entry.name }
    this.metric('input.delay', delay, labels, t)
    this.metric('input.processing', processing, labels, t)
    this.metric('input.duration', entry.duration, labels, t)
  }
  /** Cordis owns disposal of the wrapped callback; its unregister keeps the same identity.
   * Times only synchronous execution, not async waiting or subsequent promise continuations. */
  instrumentEvents(root: Context, owner: (ctx: Context) => string): void {
    if (this.restoreEvents) return
    const service = root.events
    const original = service.register
    this.subscriptions = () => {
      const counts: Record<string, number> = Object.create(null) as Record<string, number>
      for (const [name, hooks] of Object.entries(service._hooks)) {
        if (name.startsWith('internal/')) continue
        for (const hook of hooks) { const plugin = owner(hook.ctx); counts[plugin] = (counts[plugin] ?? 0) + 1 }
      }
      return counts
    }
    const run = (ctx: Context, label: string, callback: (...args: unknown[]) => unknown, receiver: unknown, args: unknown[]) => {
      if (this.disposed) return callback.apply(receiver, args)
      const start = performance.now()
      try { return callback.apply(receiver, args) }
      finally { this.event('handler', owner(ctx), label, performance.now() - start) }
    }
    const wrapped: typeof service.register = function (this: typeof service, label, hooks, callback: (...args: unknown[]) => unknown, options) {
      if (label.includes('internal/')) return original.call(this, label, hooks, callback, options)
      const ctx = (this as unknown as { ctx: Context }).ctx
      const measured = function (this: unknown, ...args: unknown[]) {
        return run(ctx, label, callback, this, args)
      }
      return original.call(this, label, hooks, measured, options)
    }
    service.register = wrapped
    this.restoreEvents = () => { if (service.register === wrapped) service.register = original }
  }
  private reactHook(): () => void {
    const existing = globals.__REACT_DEVTOOLS_GLOBAL_HOOK__
    const hook: ReactHook = existing ?? { supportsFiber: true, renderers: new Map(), inject(renderer) { const id = (this.renderers?.size ?? 0) + 1; this.renderers?.set(id, renderer); return id } }
    const original = hook.onCommitFiberRoot
    const callback: NonNullable<ReactHook['onCommitFiberRoot']> = (id, root, ...rest) => {
      if (!this.disposed) {
        try { this.commit(root) } catch { /* A renderer with another Fiber shape is unsupported. */ }
      }
      original?.call(hook, id, root, ...rest)
    }
    hook.onCommitFiberRoot = callback
    globals.__REACT_DEVTOOLS_GLOBAL_HOOK__ = hook
    return () => {
      if (hook.onCommitFiberRoot === callback) hook.onCommitFiberRoot = original
      if (!existing && globals.__REACT_DEVTOOLS_GLOBAL_HOOK__ === hook) delete globals.__REACT_DEVTOOLS_GLOBAL_HOOK__
    }
  }
  private commit(root: ReactRoot): void {
    const top = root.current
    if (!top) return
    if (top.child) this.roots.add(root)
    else this.roots.delete(root)
    const container = root.containerInfo
    const host = container instanceof Element ? container.closest<HTMLElement>('[data-perf-plugin]') : null
    const plugin = host?.dataset.perfPlugin ?? 'unattributed'
    const window = host?.dataset.perfWindow
    const duration = typeof top.actualDuration === 'number' ? top.actualDuration : null
    this.intervalCommits++; this.intervalRender += duration ?? 0
    const total = this.total(plugin)
    total.commits++; total.renderMs += duration ?? 0
    this.event('react', plugin, 'React commit', duration, undefined, window)
    const detailed = plugin === this.analysisPlugin
    const stack: { fiber: Fiber; parent: number | null; depth: number }[] = [{ fiber: top, parent: null, depth: 0 }]
    let visited = 0
    const components = new Map<string, number>()
    while (stack.length && visited++ < MAX_FIBERS) {
      const item = stack.pop()
      if (!item) continue
      const { fiber, parent, depth } = item
      let nextParent = parent, nextDepth = depth
      if (COMPONENT_TAGS.includes(fiber.tag) && (fiber.flags & 1)) {
        const name = fiber.type?.displayName ?? fiber.type?.name ?? 'Anonymous'
        components.set(name, (components.get(name) ?? 0) + 1)
        total.renders++
        if (detailed) {
          const id = this.fiberID(fiber)
          const detail: ReactDetail = { id, parent, depth, ...renderReason(fiber), selfMs: selfDuration(fiber) }
          const event = this.event('render-detail', plugin, name, fiber.actualDuration ?? null, undefined, window)
          if (event) event.detail = detail
          if (this.highlight) this.flash(fiber)
        }
      }
      if (detailed && COMPONENT_TAGS.includes(fiber.tag)) { nextParent = this.fiberID(fiber); nextDepth++ }
      if (fiber.sibling) stack.push({ fiber: fiber.sibling, parent, depth })
      if (fiber.child && (fiber.subtreeFlags === undefined || (fiber.subtreeFlags & 1))) stack.push({ fiber: fiber.child, parent: nextParent, depth: nextDepth })
    }
    for (const [name, count] of components) this.event('component', plugin, name, null, count, window)
    if (stack.length) this.event('limit', plugin, 'Component traversal truncated')
  }
  /** How many React roots have a mounted tree now (the commits seen since collection started). */
  reactRoots(): number {
    for (const root of this.roots) if (!root.current?.child) this.roots.delete(root)
    return this.roots.size
  }
  /** Cordis listeners per plugin now (what samples carry as `listeners`). */
  listenerCounts(): Record<string, number> { return this.subscriptions() }
  /** The latest native process sample; [] when none arrived in the last 3 s. */
  latestProcesses(): ProcessMetric[] { return performance.now() - this.processAt < 3000 ? this.processes : [] }
  private sample(): void {
    const t = performance.now()
    if (this.lagChannel && this.lagSent === null) { this.lagSent = t; this.lagChannel.port2.postMessage(null) }
    const visible = document.visibilityState === 'visible'
    // FPS covers the part of the interval the rAF loop ran; null when it did not run (or too
    // briefly to say), see FRAME_DEMAND_MS.
    const from = Math.max(this.lastSample, this.frameFrom)
    const framed = visible && this.framing && this.frameFrom > 0 && t - from >= 250
    const sample: PerfSample = {
      t, visible, fps: framed ? this.deltas.length * 1000 / (t - from) : null,
      frameP95: framed ? percentile(this.deltas, 0.95) : null, frameMax: framed ? percentile(this.deltas, 1) : null,
      commits: this.intervalCommits, renderMs: this.intervalRender,
      processes: t - this.processAt < 3000 ? this.processes : [], listeners: this.subscriptions(),
    }
    this.samples.push(sample)
    while (this.samples.length && this.samples[0].t < t - HISTORY) this.samples.shift()
    for (const list of [this.events, this.handlers]) {
      const first = lowerBound(list, t - HISTORY)
      if (first > 0) list.splice(0, first)
    }
    const old = lowerBound(this.dropLog, t - HISTORY)
    if (old > 0) this.dropLog.splice(0, old)
    this.lastSample = t; this.deltas = []; this.intervalCommits = 0; this.intervalRender = 0
    const bridge = globals.webkit?.messageHandlers?.tilrPerformance
    if (bridge && !this.pending) {
      this.pending = true
      void bridge.postMessage('sample').then(processes => {
        if (this.disposed) return
        const now = performance.now()
        // The request rides the page's timer: a reply long after the previous one means the
        // main thread was blocked meanwhile. That is data (a stall), shown in the window.
        if (this.replyAt && now - this.replyAt > STALL_MS && document.visibilityState === 'visible') {
          const last = this.samples.at(-1)
          if (last) { last.late = true; last.gap = now - this.replyAt }
        }
        this.replyAt = now
        this.processes = processes; this.processAt = now
      }).catch(() => { this.processes = [] }).finally(() => { this.pending = false })
    }
    for (const listener of this.listeners) listener()
    this.event('operation', 'performance', 'Sample and display', performance.now() - t)
  }
  snapshot(since = this.started): PerfRecording {
    const now = performance.now()
    const started = Math.max(since, now - HISTORY)
    const dropped: Record<string, number> = {}
    for (const d of this.dropLog) if (d.t >= started) dropped[d.kind] = (dropped[d.kind] ?? 0) + d.n
    // Both buffers are sorted by time: merge them into one list.
    const events: PerfEvent[] = []
    const a = this.events, b = this.handlers
    for (let i = lowerBound(a, since), j = lowerBound(b, since); i < a.length || j < b.length;) {
      const e = j >= b.length || (i < a.length && a[i].t <= b[j].t) ? a[i++] : b[j++]
      events.push({ ...e })
    }
    return { version: 1, origin: this.origin, react: __TILR_REACT__, started, ended: now,
      samples: this.samples.filter(s => s.t >= since).map(s => ({ ...s, processes: s.processes.map(p => ({ ...p })) })),
      events, dropped, metrics: this.metricList(started) }
  }
  metrics(): string {
    // A scrape reads frames: keep the rAF loop for FRAME_DEMAND_MS.
    this.frameUntil = performance.now() + FRAME_DEMAND_MS
    this.frames()
    const out = ['# TYPE tilr_performance_enabled gauge', 'tilr_performance_enabled 1']
    const emit = (name: string, type: string, rows: [string, number][]) => {
      out.push(`# TYPE ${name} ${type}`)
      for (const [labels, value] of rows) out.push(`${name}${labels ? '{' + labels + '}' : ''} ${value}`)
    }
    for (const [name, key, divisor] of [
      ['tilr_react_commits_total', 'commits', 1], ['tilr_react_component_renders_total', 'renders', 1],
      ['tilr_react_render_seconds_total', 'renderMs', 1000], ['tilr_plugin_loads_total', 'loads', 1],
      ['tilr_plugin_reloads_total', 'reloads', 1], ['tilr_plugin_starts_total', 'starts', 1],
      ['tilr_plugin_errors_total', 'errors', 1], ['tilr_plugin_operation_seconds_total', 'operationMs', 1000],
      ['tilr_plugin_handler_calls_total', 'handlers', 1], ['tilr_plugin_handler_seconds_total', 'handlerMs', 1000],
    ] as const) {
      if (key === 'renderMs' && __TILR_REACT__ === 'prod') continue
      emit(name, 'counter', [...this.totals].map(([plugin, total]) => [`plugin="${label(plugin)}"`, total[key] / divisor]))
    }
    emit('tilr_react_timing_available', 'gauge', [['', __TILR_REACT__ === 'prod' ? 0 : 1]])
    out.push('# TYPE tilr_plugin_load_duration_seconds histogram')
    for (const [plugin, total] of this.totals) {
      const labels = `plugin="${label(plugin)}"`
      ;['0.001', '0.01', '0.1', '1', '5', '+Inf'].forEach((bound, i) => out.push(`tilr_plugin_load_duration_seconds_bucket{${labels},le="${bound}"} ${total.loadBuckets[i]}`))
      out.push(`tilr_plugin_load_duration_seconds_sum{${labels}} ${total.loadMs / 1000}`, `tilr_plugin_load_duration_seconds_count{${labels}} ${total.loads + total.reloads}`)
    }
    out.push('# TYPE tilr_frame_interval_seconds histogram')
    ;['0.00834', '0.01667', '0.025', '0.05', '0.1', '+Inf'].forEach((bound, i) => out.push(`tilr_frame_interval_seconds_bucket{le="${bound}"} ${this.frameBuckets[i]}`))
    out.push(`tilr_frame_interval_seconds_sum ${this.frameSum}`, `tilr_frame_interval_seconds_count ${this.frameCount}`)
    const sample = this.samples.at(-1)
    if (sample) {
      emit('tilr_plugin_event_listeners', 'gauge', Object.entries(sample.listeners ?? {}).map(([plugin, count]) => [`plugin="${label(plugin)}"`, count]))
      emit('tilr_sample_timestamp_seconds', 'gauge', [['', (this.origin + sample.t) / 1000]])
      emit('tilr_page_visible', 'gauge', [['', document.visibilityState === 'visible' ? 1 : 0]])
      if (sample.fps !== null && document.visibilityState === 'visible' && performance.now() - sample.t < 3000) emit('tilr_fps', 'gauge', [['', sample.fps]])
      const processes = performance.now() - sample.t < 3000 ? sample.processes : []
      const rows = (key: 'memory' | 'cpuSeconds'): [string, number][] => processes.map(p => [`role="${label(p.name)}",scope="${label(p.scope)}",pid="${p.pid}"`, p[key]])
      emit('tilr_process_memory_bytes', 'gauge', rows('memory'))
      emit('tilr_process_cpu_seconds_total', 'counter', rows('cpuSeconds'))
    }
    const drops = Object.entries(this.dropped)
    emit('tilr_performance_dropped_events_total', 'counter', drops.filter(([kind]) => kind !== 'series' && kind !== 'invalid').map(([kind, n]) => [`kind="${label(kind)}"`, n]))
    emit('tilr_metric_dropped_total', 'counter', ['series', 'invalid'].map(reason => [`reason="${reason}"`, this.dropped[reason] ?? 0]))
    const now = performance.now()
    out.push(...metricExposition(this.metricList(now - 60_000), now))
    return out.join('\n') + '\n'
  }
  dispose(): void {
    this.disposed = true
    this.analyze(null)
    for (const observer of this.observers) observer.disconnect()
    this.observers = []
    this.lagChannel?.port1.close(); this.lagChannel?.port2.close(); this.lagChannel = undefined
    clearInterval(this.timer); this.stopFrames(); this.demands.clear()
    document.removeEventListener('visibilitychange', this.visibility)
    this.restoreHook(); this.restoreEvents?.(); this.subscriptions = () => ({})
    this.listeners.clear(); this.samples.length = 0; this.events.length = 0; this.handlers.length = 0; this.totals.clear(); this.marks.clear(); this.deltas = []; this.processes = []
    this.series.clear(); this.dropLog = []; this.roots.clear()
    void globals.webkit?.messageHandlers?.tilrPerformance?.postMessage('reset').catch(() => {})
  }
}

/**
 * A rendered component's own time: its actualDuration minus its children's, but only when the
 * children are from this commit. A fiber that bailed out on its children (`alternate.child ===
 * child`, React's own test in bubbleProperties) still points at the fibers of an earlier commit,
 * whose actualDuration is stale, and React did not add them to its own duration. Children the
 * fiber reconciled are fresh (createWorkInProgress resets their duration), host and memo
 * children included: their duration holds the work below them done in this commit.
 */
export function selfDuration(fiber: Fiber): number | null {
  if (typeof fiber.actualDuration !== 'number') return null
  let self = fiber.actualDuration
  if (!fiber.alternate || fiber.alternate.child !== fiber.child) {
    for (let child = fiber.child, n = 0; child && n++ < MAX_FIBERS; child = child.sibling) self -= child.actualDuration ?? 0
  }
  return Math.max(0, self)
}
